ue,"ap_incident_elapsed":{"param":"LEGAL.DATA_INCIDENT_NOTICE_HOURS","mas":0}},"esperado":true},{"casuistica":"BAJO_EL_LIMITE","entrada":{"ap_qualifying_data_incident":true,"ap_incident_qualifying_scope_ignored":false,"ap_incident_knowledge_anchor_wrong":false,"ap_incident_anpdp_missing":false,"ap_incident_cnsd_missing":false,"ap_incident_role_not_central":false,"ap_incident_role_not_gg":false,"ap_incident_responsible_hardcoded":false,"ap_incident_elapsed":{"param":"LEGAL.DATA_INCIDENT_NOTICE_HOURS","mas":-1}},"esperado":false},{"casuistica":"EN_EL_LIMITE","entrada":{"ap_qualifying_data_incident":true,"ap_incident_qualifying_scope_ignored":false,"ap_incident_knowledge_anchor_wrong":false,"ap_incident_anpdp_missing":false,"ap_incident_cnsd_missing":false,"ap_incident_role_not_central":false,"ap_incident_role_not_gg":false,"ap_incident_responsible_hardcoded":false,"ap_incident_elapsed":{"param":"LEGAL.DATA_INCIDENT_NOTICE_HOURS","mas":0}},"esperado":false},{"casuistica":"SOBRE_EL_LIMITE","entrada":{"ap_qualifying_data_incident":true,"ap_incident_qualifying_scope_ignored":false,"ap_incident_knowledge_anchor_wrong":false,"ap_incident_anpdp_missing":false,"ap_incident_cnsd_missing":false,"ap_incident_role_not_central":false,"ap_incident_role_not_gg":false,"ap_incident_responsible_hardcoded":false,"ap_incident_elapsed":{"param":"LEGAL.DATA_INCIDENT_NOTICE_HOURS","mas":1}},"esperado":true}]},"hash_paquete":"b871c8505e241387a3ced44dedd26fa15d15d9f83260baab561d3c3b8e978494","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; t record; n int:=0; vectors int:=0; b_leg jsonb; b_dep jsonb; b_cfg jsonb; val jsonb; lid int; residual text; diff text; old_desc text; new_desc text; links int:=0; before_replaced int; after_replaced int; direct_hash text; c jsonb;
BEGIN
 IF lf_ops.nucleo_param_valor_v1('CLIENT.ONB_EARLY_STEPPER_TOTAL') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='ONB_EARLY_STEPPER_TOTAL' AND hecho='ap_early_total') THEN RAISE EXCEPTION 'S22AP_PARAM_PREFLIGHT CLIENT.ONB_EARLY_STEPPER_TOTAL'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.ONB_LATE_STEPPER_TOTAL') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='ONB_LATE_STEPPER_TOTAL' AND hecho='ap_late_total') THEN RAISE EXCEPTION 'S22AP_PARAM_PREFLIGHT CLIENT.ONB_LATE_STEPPER_TOTAL'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.ONB003_STEPPER_ORDINAL') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='ONB003_STEPPER_ORDINAL' AND hecho='ap_onb003_ordinal') THEN RAISE EXCEPTION 'S22AP_PARAM_PREFLIGHT CLIENT.ONB003_STEPPER_ORDINAL'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.ONB003_STEPPER_PENDING_SEGMENTS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='ONB003_STEPPER_PENDING_SEGMENTS' AND hecho='ap_onb003_pending') THEN RAISE EXCEPTION 'S22AP_PARAM_PREFLIGHT CLIENT.ONB003_STEPPER_PENDING_SEGMENTS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('LEGAL.SIREC_ANNUAL_REVENUE_UIT_THRESHOLD') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='LEGAL' AND config_key='SIREC_ANNUAL_REVENUE_UIT_THRESHOLD' AND hecho='ap_sirec_threshold') THEN RAISE EXCEPTION 'S22AP_PARAM_PREFLIGHT LEGAL.SIREC_ANNUAL_REVENUE_UIT_THRESHOLD'; END IF;
 IF lf_ops.nucleo_param_valor_v1('LEGAL.DATA_INCIDENT_NOTICE_HOURS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='LEGAL' AND config_key='DATA_INCIDENT_NOTICE_HOURS' AND hecho='ap_incident_elapsed') THEN RAISE EXCEPTION 'S22AP_PARAM_PREFLIGHT LEGAL.DATA_INCIDENT_NOTICE_HOURS'; END IF;
 SELECT count(DISTINCT legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT count(DISTINCT (cv.coverage->>'legacy_id')::bigint) INTO expected_delta FROM jsonb_array_elements(packs) AS pk(package) CROSS JOIN LATERAL jsonb_array_elements(pk.package->'coberturas') AS cv(coverage) WHERE cv.coverage->>'estado_cobertura'='REEMPLAZADA' AND NOT EXISTS (SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada AS existing_cov WHERE existing_cov.legacy_id=(cv.coverage->>'legacy_id')::bigint AND existing_cov.estado_cobertura='REEMPLAZADA');
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' THEN RAISE EXCEPTION 'S22_ATTESTATION_DRIFT %',cd; END IF;
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22_VECTOR_FAIL %',cd; END IF; vectors:=vectors+1; END LOOP;
 val:=jsonb_build_object('regla',cd,'hash_evaluado',h,'veredicto','PASS','puntajes',p->'puntajes','juez','Claude','modo','INDEPENDIENTE','revisor_es_productor',false,'llamadas_modelo',1,'evidencia_ref','Claude 2026-11-26 06:25 Lima: Revisado conforme; 8 paquetes, 575 reemplazada y cinco legadas parciales con residual; juicio V3 independiente');
 BEGIN
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val||jsonb_build_object('hash_evaluado',repeat('0',64)));
 RAISE EXCEPTION 'S22AP_NEGATIVE_HASH_ACCEPTED %',cd;
 EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF; END;
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val);
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF ans->>'decision' IS DISTINCT FROM 'AUTO' THEN RAISE EXCEPTION 'S22AP_NOT_AUTO % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_promover_v1(cd);
 IF ans->>'resultado' IS DISTINCT FROM 'PROMOVIDA_AUTO' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S22AP_PROMOTION_FAIL % %',cd,ans; END IF;
 n:=n+1;
 END LOOP;
 IF n<>jsonb_array_length(packs) OR vectors<>(SELECT coalesce(sum(jsonb_array_length(value->'paquete'->'pruebas')),0) FROM jsonb_array_elements(packs)) THEN RAISE EXCEPTION 'S22_VECTOR_COUNT'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22_INVARIANT_FAIL'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22_DPIG03_FAIL'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 cd:=p->>'codigo'; h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' THEN RAISE EXCEPTION 'S22AP_COVERAGE_HASH_DRIFT %',cd; END IF;
 FOR c IN SELECT value FROM jsonb_array_elements(p->'coberturas') LOOP
 lid:=(c->>'legacy_id')::int; residual:=c->>'residual'; diff:=c->>'diferencias';
 IF length(diff)<30 OR c->>'estado_cobertura' NOT IN ('REEMPLAZADA','PARCIAL') OR (c->>'estado_cobertura'='REEMPLAZADA' AND residual IS DISTINCT FROM '') OR (c->>'estado_cobertura'='PARCIAL' AND coalesce(length(residual),0)<15) THEN RAISE EXCEPTION 'S22AP_COVERAGE_CONTRACT %',lid; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 VALUES(lid,cd,1,c->>'estado_cobertura',diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||(p->'paquete'->>'descripcion')||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente 2026-11-26 06:25 Lima'),h,'GPT / Claude S22-AP independiente')
 ON CONFLICT (legacy_id,nucleo_codigo,version_nucleo) DO UPDATE SET estado_cobertura=EXCLUDED.estado_cobertura, diferencias=EXCLUDED.diferencias, evidencia=EXCLUDED.evidencia, hash_paquete=EXCLUDED.hash_paquete, revisado_por=EXCLUDED.revisado_por;
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S22AP_SOURCE_MISSING %',lid; END IF;
 END LOOP;
 END LOOP;
 SELECT count(DISTINCT legacy_id) INTO after_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 IF (SELECT count(*) FROM lf_ops.reglas)=586 AND (links<>(SELECT coalesce(sum(jsonb_array_length(value->'coberturas')),0) FROM jsonb_array_elements(packs)) OR after_replaced<>before_replaced+expected_delta) THEN RAISE EXCEPTION 'S22AP_COVERAGE_READBACK_FAIL links=% before=% after=%',links,before_replaced,after_replaced; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22AP_POST_COVERAGE_INVARIANT_FAIL'; END IF;
 RAISE NOTICE 'S22AP_PASS JUICIOS=% AUTO=% VECTORES=% links=% replaced=% DPIG03=0',n,n,vectors,links,after_replaced;
END $ap$;
COMMIT;
